FROM typed
QUALIFY `address_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `address_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.loyalty_account ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_loyalty_account (
  CONSTRAINT `loyalty_account_id_not_null` EXPECT (`loyalty_account_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: consumer.loyalty_account typed and cleaned, one row per loyalty_account_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`loyalty_account_id`), '') AS BIGINT) AS `loyalty_account_id`,
    TRY_CAST(NULLIF(trim(`consent_record_id`), '') AS BIGINT) AS `consent_record_id`,
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`loyalty_tier_id`), '') AS BIGINT) AS `loyalty_tier_id`,
    TRY_CAST(NULLIF(trim(`pos_transaction_id`), '') AS BIGINT) AS `pos_transaction_id`,
    TRY_CAST(NULLIF(trim(`referral_account_loyalty_account_id`), '') AS BIGINT) AS `referral_account_loyalty_account_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    NULLIF(trim(`account_number`), '') AS `account_number`,
    CASE lower(trim(`account_status`))
      WHEN 'active' THEN 'active'
      WHEN 'suspended' THEN 'suspended'
      WHEN 'closed' THEN 'closed'
      WHEN 'pending' THEN 'pending'
      WHEN 'frozen' THEN 'frozen'
      ELSE NULLIF(trim(`account_status`), '')
    END AS `account_status`,
    CASE lower(trim(`account_type`))
      WHEN 'individual' THEN 'individual'
      WHEN 'household' THEN 'household'
      WHEN 'business' THEN 'business'
      WHEN 'coalition' THEN 'coalition'
      ELSE NULLIF(trim(`account_type`), '')
    END AS `account_type`,
    CASE lower(trim(`cltv_segment`))
      WHEN 'high_value' THEN 'high_value'
      WHEN 'mid_value' THEN 'mid_value'
      WHEN 'low_value' THEN 'low_value'
      WHEN 'at_risk' THEN 'at_risk'
      WHEN 'lapsed' THEN 'lapsed'
      ELSE NULLIF(trim(`cltv_segment`), '')
    END AS `cltv_segment`,
    CASE lower(trim(`communication_preference`))
      WHEN 'email' THEN 'email'
      WHEN 'sms' THEN 'sms'
      WHEN 'push' THEN 'push'
      WHEN 'post' THEN 'post'
      WHEN 'none' THEN 'none'
      ELSE NULLIF(trim(`communication_preference`), '')
    END AS `communication_preference`,
    CASE WHEN lower(trim(`consent_data_sharing`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`consent_data_sharing`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `consent_data_sharing`,
    CASE WHEN lower(trim(`consent_marketing`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`consent_marketing`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `consent_marketing`,
    COALESCE(try_to_timestamp(trim(`consent_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`consent_timestamp`) AS TIMESTAMP)) AS `consent_timestamp`,
    NULLIF(trim(`country_code`), '') AS `country_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE lower(trim(`enrollment_channel`))
      WHEN 'web' THEN 'web'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'in_store' THEN 'in_store'
      WHEN 'call_center' THEN 'call_center'
      WHEN 'partner' THEN 'partner'
      WHEN 'dtc' THEN 'dtc'
      ELSE NULLIF(trim(`enrollment_channel`), '')
    END AS `enrollment_channel`,
    COALESCE(try_to_date(trim(`enrollment_date`), 'yyyy-MM-dd'), try_to_date(trim(`enrollment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`enrollment_date`) AS DATE)) AS `enrollment_date`,
    NULLIF(trim(`enrollment_source_code`), '') AS `enrollment_source_code`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    CASE WHEN lower(trim(`fraud_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`fraud_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `fraud_flag`,
    COALESCE(try_to_date(trim(`fraud_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`fraud_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`fraud_review_date`) AS DATE)) AS `fraud_review_date`,
    NULLIF(trim(`language_code`), '') AS `language_code`,
    COALESCE(try_to_date(trim(`last_activity_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_activity_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_activity_date`) AS DATE)) AS `last_activity_date`,
    COALESCE(try_to_date(trim(`last_earn_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_earn_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_earn_date`) AS DATE)) AS `last_earn_date`,
    COALESCE(try_to_date(trim(`last_redemption_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_redemption_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_redemption_date`) AS DATE)) AS `last_redemption_date`,
    TRY_CAST(NULLIF(trim(`lifetime_points_earned`), '') AS DECIMAL(18,4)) AS `lifetime_points_earned`,
    TRY_CAST(NULLIF(trim(`lifetime_points_expired`), '') AS DECIMAL(18,4)) AS `lifetime_points_expired`,
    TRY_CAST(NULLIF(trim(`lifetime_points_redeemed`), '') AS DECIMAL(18,4)) AS `lifetime_points_redeemed`,
    TRY_CAST(NULLIF(trim(`nps_score`), '') AS INT) AS `nps_score`,
    COALESCE(try_to_date(trim(`nps_survey_date`), 'yyyy-MM-dd'), try_to_date(trim(`nps_survey_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`nps_survey_date`) AS DATE)) AS `nps_survey_date`,
    COALESCE(try_to_date(trim(`opt_out_date`), 'yyyy-MM-dd'), try_to_date(trim(`opt_out_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`opt_out_date`) AS DATE)) AS `opt_out_date`,
    TRY_CAST(NULLIF(trim(`points_balance`), '') AS DECIMAL(18,4)) AS `points_balance`,
    NULLIF(trim(`points_currency_code`), '') AS `points_currency_code`,
    CASE lower(trim(`points_expiry_policy`))
      WHEN 'rolling_12_months' THEN 'rolling_12_months'
      WHEN 'annual' THEN 'annual'
      WHEN 'never' THEN 'never'
      WHEN 'program_end' THEN 'program_end'
      WHEN 'activity_based' THEN 'activity_based'
      ELSE NULLIF(trim(`points_expiry_policy`), '')
    END AS `points_expiry_policy`,
    CASE lower(trim(`preferred_redemption_type`))
      WHEN 'discount' THEN 'discount'
      WHEN 'free_product' THEN 'free_product'
      WHEN 'gift_card' THEN 'gift_card'
      WHEN 'charity' THEN 'charity'
      WHEN 'cashback' THEN 'cashback'
      WHEN 'experience' THEN 'experience'
      ELSE NULLIF(trim(`preferred_redemption_type`), '')
    END AS `preferred_redemption_type`,
    CASE lower(trim(`previous_tier`))
      WHEN 'standard' THEN 'standard'
      WHEN 'silver' THEN 'silver'
      WHEN 'gold' THEN 'gold'
      WHEN 'platinum' THEN 'platinum'
      WHEN 'elite' THEN 'elite'
      ELSE NULLIF(trim(`previous_tier`), '')
    END AS `previous_tier`,
    CASE lower(trim(`source_system_code`))
      WHEN 'sfcgc' THEN 'SFCGC'
      WHEN 'sap_s4' THEN 'SAP_S4'
      WHEN 'oracle_erp' THEN 'ORACLE_ERP'
      WHEN 'custom_crm' THEN 'CUSTOM_CRM'
      WHEN 'tradeedge' THEN 'TRADEEDGE'
      ELSE NULLIF(trim(`source_system_code`), '')
    END AS `source_system_code`,
    COALESCE(try_to_date(trim(`tier_effective_date`), 'yyyy-MM-dd'), try_to_date(trim(`tier_effective_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`tier_effective_date`) AS DATE)) AS `tier_effective_date`,
    TRY_CAST(NULLIF(trim(`tier_qualification_spend`), '') AS DECIMAL(18,2)) AS `tier_qualification_spend`,
    COALESCE(try_to_date(trim(`tier_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`tier_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`tier_review_date`) AS DATE)) AS `tier_review_date`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_loyalty_account
)
SELECT *
FROM typed
QUALIFY `loyalty_account_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `loyalty_account_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.loyalty_transaction ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_loyalty_transaction (
  CONSTRAINT `loyalty_transaction_id_not_null` EXPECT (`loyalty_transaction_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `qualifying_spend_amount_not_negative` EXPECT (`qualifying_spend_amount` IS NULL OR `qualifying_spend_amount` >= 0)
)
COMMENT 'Silver: consumer.loyalty_transaction typed and cleaned, one row per loyalty_transaction_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`loyalty_transaction_id`), '') AS BIGINT) AS `loyalty_transaction_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`loyalty_account_id`), '') AS BIGINT) AS `loyalty_account_id`,
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`loyalty_tier_id`), '') AS BIGINT) AS `loyalty_tier_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`pos_transaction_id`), '') AS BIGINT) AS `pos_transaction_id`,
    TRY_CAST(NULLIF(trim(`reversal_reference_loyalty_transaction_id`), '') AS BIGINT) AS `reversal_reference_loyalty_transaction_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    NULLIF(trim(`adjustment_notes`), '') AS `adjustment_notes`,
    NULLIF(trim(`adjustment_reason_code`), '') AS `adjustment_reason_code`,
    TRY_CAST(NULLIF(trim(`bonus_multiplier`), '') AS DECIMAL(6,4)) AS `bonus_multiplier`,
    CASE lower(trim(`channel`))
      WHEN 'ecommerce' THEN 'ecommerce'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'retail_store' THEN 'retail_store'
      WHEN 'dtc_website' THEN 'dtc_website'
      WHEN 'call_centre' THEN 'call_centre'
      WHEN 'kiosk' THEN 'kiosk'
      ELSE NULLIF(trim(`channel`), '')
    END AS `channel`,
    CASE WHEN lower(trim(`consent_verified`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`consent_verified`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `consent_verified`,
    NULLIF(trim(`country_code`), '') AS `country_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    CASE WHEN lower(trim(`data_retention_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`data_retention_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `data_retention_flag`,
    TRY_CAST(NULLIF(trim(`earn_rate`), '') AS DECIMAL(10,6)) AS `earn_rate`,
    CASE WHEN lower(trim(`fraud_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`fraud_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `fraud_flag`,
    CASE lower(trim(`fraud_review_status`))
      WHEN 'not_reviewed' THEN 'not_reviewed'
      WHEN 'under_review' THEN 'under_review'
      WHEN 'cleared' THEN 'cleared'
      WHEN 'confirmed_fraud' THEN 'confirmed_fraud'
      ELSE NULLIF(trim(`fraud_review_status`), '')
    END AS `fraud_review_status`,
    CASE WHEN lower(trim(`is_bonus_transaction`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_bonus_transaction`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_bonus_transaction`,
    TRY_CAST(NULLIF(trim(`monetary_value`), '') AS DECIMAL(18,2)) AS `monetary_value`,
    TRY_CAST(NULLIF(trim(`points_amount`), '') AS DECIMAL(18,4)) AS `points_amount`,
    TRY_CAST(NULLIF(trim(`points_balance_after`), '') AS DECIMAL(18,4)) AS `points_balance_after`,
    TRY_CAST(NULLIF(trim(`points_balance_before`), '') AS DECIMAL(18,4)) AS `points_balance_before`,
    CASE lower(trim(`points_direction`))
      WHEN 'credit' THEN 'credit'
      WHEN 'debit' THEN 'debit'
      ELSE NULLIF(trim(`points_direction`), '')
    END AS `points_direction`,
    COALESCE(try_to_date(trim(`points_expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`points_expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`points_expiry_date`) AS DATE)) AS `points_expiry_date`,
    CASE WHEN lower(trim(`points_liability_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`points_liability_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `points_liability_flag`,
    COALESCE(try_to_timestamp(trim(`processing_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`processing_timestamp`) AS TIMESTAMP)) AS `processing_timestamp`,
    TRY_CAST(NULLIF(trim(`program_year`), '') AS INT) AS `program_year`,
    TRY_CAST(NULLIF(trim(`qualifying_spend_amount`), '') AS DECIMAL(18,2)) AS `qualifying_spend_amount`,
    TRY_CAST(NULLIF(trim(`redemption_value`), '') AS DECIMAL(18,2)) AS `redemption_value`,
    NULLIF(trim(`source_transaction_ref`), '') AS `source_transaction_ref`,
    NULLIF(trim(`transaction_number`), '') AS `transaction_number`,
    CASE lower(trim(`transaction_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'processed' THEN 'processed'
      WHEN 'reversed' THEN 'reversed'
      WHEN 'failed' THEN 'failed'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`transaction_status`), '')
    END AS `transaction_status`,
    COALESCE(try_to_timestamp(trim(`transaction_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`transaction_timestamp`) AS TIMESTAMP)) AS `transaction_timestamp`,
    CASE lower(trim(`transaction_type`))
      WHEN 'earn' THEN 'earn'
      WHEN 'redeem' THEN 'redeem'
      WHEN 'adjust' THEN 'adjust'
      WHEN 'expire' THEN 'expire'
      WHEN 'transfer' THEN 'transfer'
      WHEN 'reversal' THEN 'reversal'
      ELSE NULLIF(trim(`transaction_type`), '')
    END AS `transaction_type`,
    NULLIF(trim(`trigger_event`), '') AS `trigger_event`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_loyalty_transaction
)
SELECT *
FROM typed
QUALIFY `loyalty_transaction_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `loyalty_transaction_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.preference ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_preference (
  CONSTRAINT `preference_id_not_null` EXPECT (`preference_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: consumer.preference typed and cleaned, one row per preference_id (latest last_updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`preference_id`), '') AS BIGINT) AS `preference_id`,
    TRY_CAST(NULLIF(trim(`brand_id`), '') AS BIGINT) AS `brand_id`,
    TRY_CAST(NULLIF(trim(`consent_record_id`), '') AS BIGINT) AS `consent_record_id`,
    TRY_CAST(NULLIF(trim(`household_id`), '') AS BIGINT) AS `household_id`,
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    CASE WHEN lower(trim(`brand_override_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`brand_override_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `brand_override_flag`,
    CASE lower(trim(`brand_override_reason`))
      WHEN 'regulatory_restriction' THEN 'regulatory_restriction'
      WHEN 'brand_policy' THEN 'brand_policy'
      WHEN 'consumer_request' THEN 'consumer_request'
      WHEN 'loyalty_program_rule' THEN 'loyalty_program_rule'
      WHEN 'campaign_exclusion' THEN 'campaign_exclusion'
      ELSE NULLIF(trim(`brand_override_reason`), '')
    END AS `brand_override_reason`,
    NULLIF(trim(`category`), '') AS `category`,
    CASE lower(trim(`cltv_tier`))
      WHEN 'platinum' THEN 'platinum'
      WHEN 'gold' THEN 'gold'
      WHEN 'silver' THEN 'silver'
      WHEN 'bronze' THEN 'bronze'
      WHEN 'unclassified' THEN 'unclassified'
      ELSE NULLIF(trim(`cltv_tier`), '')
    END AS `cltv_tier`,
    TRY_CAST(NULLIF(trim(`confidence_score`), '') AS DECIMAL(5,4)) AS `confidence_score`,
    CASE lower(trim(`consent_basis`))
      WHEN 'explicit_consent' THEN 'explicit_consent'
      WHEN 'legitimate_interest' THEN 'legitimate_interest'
      WHEN 'contractual_necessity' THEN 'contractual_necessity'
      WHEN 'legal_obligation' THEN 'legal_obligation'
      WHEN 'vital_interest' THEN 'vital_interest'
      WHEN 'public_task' THEN 'public_task'
      ELSE NULLIF(trim(`consent_basis`), '')
    END AS `consent_basis`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`data_subject_request_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`data_subject_request_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `data_subject_request_flag`,
    COALESCE(try_to_date(trim(`effective_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_date`) AS DATE)) AS `effective_date`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    NULLIF(trim(`flavor_fragrance_preference`), '') AS `flavor_fragrance_preference`,
    NULLIF(trim(`geographic_scope`), '') AS `geographic_scope`,
    CASE lower(trim(`inference_basis`))
      WHEN 'purchase_history' THEN 'purchase_history'
      WHEN 'browsing_behavior' THEN 'browsing_behavior'
      WHEN 'survey_response' THEN 'survey_response'
      WHEN 'loyalty_redemption' THEN 'loyalty_redemption'
      WHEN 'pos_transaction' THEN 'pos_transaction'
      WHEN 'panel_data' THEN 'panel_data'
      ELSE NULLIF(trim(`inference_basis`), '')
    END AS `inference_basis`,
    NULLIF(trim(`inference_model_version`), '') AS `inference_model_version`,
    CASE WHEN lower(trim(`is_global_preference`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_global_preference`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_global_preference`,
    COALESCE(try_to_timestamp(trim(`last_updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_updated_timestamp`) AS TIMESTAMP)) AS `last_updated_timestamp`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE lower(trim(`nps_segment`))
      WHEN 'promoter' THEN 'promoter'
      WHEN 'passive' THEN 'passive'
      WHEN 'detractor' THEN 'detractor'
      WHEN 'unknown' THEN 'unknown'
      ELSE NULLIF(trim(`nps_segment`), '')
    END AS `nps_segment`,
    CASE WHEN lower(trim(`opt_in_status`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`opt_in_status`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `opt_in_status`,
    NULLIF(trim(`pack_size_preference`), '') AS `pack_size_preference`,
    CASE lower(trim(`preference_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'pending_verification' THEN 'pending_verification'
      WHEN 'suppressed' THEN 'suppressed'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`preference_status`), '')
    END AS `preference_status`,
    NULLIF(trim(`preferred_channel`), '') AS `preferred_channel`,
    NULLIF(trim(`preferred_contact_frequency`), '') AS `preferred_contact_frequency`,
    NULLIF(trim(`preferred_language`), '') AS `preferred_language`,
    CASE lower(trim(`preferred_time_of_day`))
      WHEN 'morning' THEN 'morning'
      WHEN 'afternoon' THEN 'afternoon'
      WHEN 'evening' THEN 'evening'
      WHEN 'night' THEN 'night'
      WHEN 'no_preference' THEN 'no_preference'
      ELSE NULLIF(trim(`preferred_time_of_day`), '')
    END AS `preferred_time_of_day`,
    NULLIF(trim(`preferred_timezone`), '') AS `preferred_timezone`,
    TRY_CAST(NULLIF(trim(`rank`), '') AS INT) AS `rank`,
    NULLIF(trim(`retail_channel_preference`), '') AS `retail_channel_preference`,
    NULLIF(trim(`sku_preference`), '') AS `sku_preference`,
    NULLIF(trim(`source`), '') AS `source`,
    NULLIF(trim(`source_system_preference_ref`), '') AS `source_system_preference_ref`,
    NULLIF(trim(`subcategory`), '') AS `subcategory`,
    CASE lower(trim(`suppression_reason`))
      WHEN 'gdpr_erasure' THEN 'gdpr_erasure'
      WHEN 'ccpa_opt_out' THEN 'ccpa_opt_out'
      WHEN 'consumer_request' THEN 'consumer_request'
      WHEN 'regulatory_hold' THEN 'regulatory_hold'
      WHEN 'fraud_flag' THEN 'fraud_flag'
      WHEN 'deceased' THEN 'deceased'
      ELSE NULLIF(trim(`suppression_reason`), '')
    END AS `suppression_reason`,
    TRY_CAST(NULLIF(trim(`value`), '') AS DECIMAL(18,2)) AS `value`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_preference
)
SELECT *
FROM typed
QUALIFY `preference_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `preference_id` ORDER BY `last_updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.consent_record ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_consent_record (
  CONSTRAINT `consent_record_id_not_null` EXPECT (`consent_record_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: consumer.consent_record typed and cleaned, one row per consent_record_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`consent_record_id`), '') AS BIGINT) AS `consent_record_id`,
    TRY_CAST(NULLIF(trim(`brand_id`), '') AS BIGINT) AS `brand_id`,
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    CASE lower(trim(`capture_method`))
      WHEN 'web_form' THEN 'web_form'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'in_store' THEN 'in_store'
      WHEN 'call_center' THEN 'call_center'
      WHEN 'paper_form' THEN 'paper_form'
      WHEN 'email_link' THEN 'email_link'
      ELSE NULLIF(trim(`capture_method`), '')
    END AS `capture_method`,
    COALESCE(try_to_timestamp(trim(`capture_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`capture_timestamp`) AS TIMESTAMP)) AS `capture_timestamp`,
    CASE lower(trim(`change_trigger`))
      WHEN 'consumer_action' THEN 'consumer_action'
      WHEN 'system_expiry' THEN 'system_expiry'
      WHEN 'admin_override' THEN 'admin_override'
      WHEN 'legal_request' THEN 'legal_request'
      WHEN 'data_breach' THEN 'data_breach'
      WHEN 're_consent_campaign' THEN 're_consent_campaign'
      ELSE NULLIF(trim(`change_trigger`), '')
    END AS `change_trigger`,
    NULLIF(trim(`consent_language_code`), '') AS `consent_language_code`,
    NULLIF(trim(`consent_proof_reference`), '') AS `consent_proof_reference`,
    CASE lower(trim(`consent_scope`))
      WHEN 'global' THEN 'global'
      WHEN 'brand_specific' THEN 'brand_specific'
      WHEN 'product_category' THEN 'product_category'
      WHEN 'campaign_specific' THEN 'campaign_specific'
      ELSE NULLIF(trim(`consent_scope`), '')
    END AS `consent_scope`,
    CASE lower(trim(`consent_status`))
      WHEN 'granted' THEN 'granted'
      WHEN 'withdrawn' THEN 'withdrawn'
      WHEN 'pending' THEN 'pending'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`consent_status`), '')
    END AS `consent_status`,
    NULLIF(trim(`consent_text_snapshot`), '') AS `consent_text_snapshot`,
    CASE lower(trim(`consent_type`))
      WHEN 'marketing_email' THEN 'marketing_email'
      WHEN 'sms' THEN 'sms'
      WHEN 'push_notification' THEN 'push_notification'
      WHEN 'data_sharing' THEN 'data_sharing'
      WHEN 'profiling' THEN 'profiling'
      WHEN 'cookies' THEN 'cookies'
      ELSE NULLIF(trim(`consent_type`), '')
    END AS `consent_type`,
    NULLIF(trim(`consent_version`), '') AS `consent_version`,
    NULLIF(trim(`cookie_consent_categories`), '') AS `cookie_consent_categories`,
    NULLIF(trim(`country_code`), '') AS `country_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE lower(trim(`device_type`))
      WHEN 'desktop' THEN 'desktop'
      WHEN 'mobile' THEN 'mobile'
      WHEN 'tablet' THEN 'tablet'
      WHEN 'kiosk' THEN 'kiosk'
      WHEN 'other' THEN 'other'
      ELSE NULLIF(trim(`device_type`), '')
    END AS `device_type`,
    CASE WHEN lower(trim(`double_opt_in_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`double_opt_in_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `double_opt_in_flag`,
    COALESCE(try_to_timestamp(trim(`double_opt_in_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`double_opt_in_timestamp`) AS TIMESTAMP)) AS `double_opt_in_timestamp`,
    COALESCE(try_to_date(trim(`effective_from`), 'yyyy-MM-dd'), try_to_date(trim(`effective_from`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_from`) AS DATE)) AS `effective_from`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    NULLIF(trim(`ip_address`), '') AS `ip_address`,
    CASE WHEN lower(trim(`is_current_record`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_current_record`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_current_record`,
    CASE lower(trim(`legal_basis`))
      WHEN 'consent' THEN 'consent'
      WHEN 'legitimate_interest' THEN 'legitimate_interest'
      WHEN 'contract' THEN 'contract'
      WHEN 'legal_obligation' THEN 'legal_obligation'
      WHEN 'vital_interest' THEN 'vital_interest'
      WHEN 'public_task' THEN 'public_task'
      ELSE NULLIF(trim(`legal_basis`), '')
    END AS `legal_basis`,
    TRY_CAST(NULLIF(trim(`minor_age_threshold`), '') AS INT) AS `minor_age_threshold`,
    CASE WHEN lower(trim(`parental_consent_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`parental_consent_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `parental_consent_flag`,
    CASE lower(trim(`prior_consent_status`))
      WHEN 'granted' THEN 'granted'
      WHEN 'withdrawn' THEN 'withdrawn'
      WHEN 'pending' THEN 'pending'
      WHEN 'expired' THEN 'expired'
      WHEN 'none' THEN 'none'
      ELSE NULLIF(trim(`prior_consent_status`), '')
    END AS `prior_consent_status`,
    NULLIF(trim(`processing_agent`), '') AS `processing_agent`,
    CASE WHEN lower(trim(`profiling_consent_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`profiling_consent_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `profiling_consent_flag`,
    COALESCE(try_to_date(trim(`re_consent_deadline`), 'yyyy-MM-dd'), try_to_date(trim(`re_consent_deadline`), 'dd/MM/yyyy'), TRY_CAST(trim(`re_consent_deadline`) AS DATE)) AS `re_consent_deadline`,
    CASE WHEN lower(trim(`re_consent_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`re_consent_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `re_consent_required_flag`,
    TRY_CAST(NULLIF(trim(`record_version`), '') AS INT) AS `record_version`,
    CASE lower(trim(`regulatory_jurisdiction`))
      WHEN 'gdpr' THEN 'GDPR'
      WHEN 'ccpa' THEN 'CCPA'
      WHEN 'lgpd' THEN 'LGPD'
      WHEN 'pipeda' THEN 'PIPEDA'
      WHEN 'pdpa' THEN 'PDPA'
      WHEN 'other' THEN 'OTHER'
      ELSE NULLIF(trim(`regulatory_jurisdiction`), '')
    END AS `regulatory_jurisdiction`,
    TRY_CAST(NULLIF(trim(`retention_period_days`), '') AS INT) AS `retention_period_days`,
    CASE WHEN lower(trim(`third_party_sharing_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`third_party_sharing_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `third_party_sharing_flag`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    CASE lower(trim(`withdrawal_method`))
      WHEN 'web_form' THEN 'web_form'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'in_store' THEN 'in_store'
      WHEN 'call_center' THEN 'call_center'
      WHEN 'email_link' THEN 'email_link'
      WHEN 'automated_expiry' THEN 'automated_expiry'
      ELSE NULLIF(trim(`withdrawal_method`), '')
    END AS `withdrawal_method`,
    COALESCE(try_to_timestamp(trim(`withdrawal_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`withdrawal_timestamp`) AS TIMESTAMP)) AS `withdrawal_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_consent_record
)
SELECT *
FROM typed
QUALIFY `consent_record_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `consent_record_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.dtc_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_dtc_order (
  CONSTRAINT `dtc_order_id_not_null` EXPECT (`dtc_order_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `subtotal_amount_not_negative` EXPECT (`subtotal_amount` IS NULL OR `subtotal_amount` >= 0),
  CONSTRAINT `discount_amount_not_negative` EXPECT (`discount_amount` IS NULL OR `discount_amount` >= 0),
  CONSTRAINT `shipping_amount_not_negative` EXPECT (`shipping_amount` IS NULL OR `shipping_amount` >= 0),
  CONSTRAINT `tax_amount_not_negative` EXPECT (`tax_amount` IS NULL OR `tax_amount` >= 0),
  CONSTRAINT `order_total_amount_not_negative` EXPECT (`order_total_amount` IS NULL OR `order_total_amount` >= 0)
)
COMMENT 'Silver: consumer.dtc_order typed and cleaned, one row per dtc_order_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`dtc_order_id`), '') AS BIGINT) AS `dtc_order_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`loyalty_account_id`), '') AS BIGINT) AS `loyalty_account_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_id`), '') AS BIGINT) AS `outbound_order_id`,
    TRY_CAST(NULLIF(trim(`primary_dtc_procurement_purchase_order_id`), '') AS BIGINT) AS `primary_dtc_procurement_purchase_order_id`,
    TRY_CAST(NULLIF(trim(`ship_to_address_id`), '') AS BIGINT) AS `ship_to_address_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`subscription_id`), '') AS BIGINT) AS `subscription_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`actual_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_delivery_date`) AS DATE)) AS `actual_delivery_date`,
    CASE WHEN lower(trim(`billing_address_same_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`billing_address_same_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `billing_address_same_flag`,
    NULLIF(trim(`carrier_code`), '') AS `carrier_code`,
    CASE lower(trim(`channel_code`))
      WHEN 'brand_website' THEN 'brand_website'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'social_commerce' THEN 'social_commerce'
      WHEN 'voice_commerce' THEN 'voice_commerce'
      WHEN 'dtc_subscription' THEN 'dtc_subscription'
      ELSE NULLIF(trim(`channel_code`), '')
    END AS `channel_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    CASE lower(trim(`device_type`))
      WHEN 'desktop' THEN 'desktop'
      WHEN 'mobile' THEN 'mobile'
      WHEN 'tablet' THEN 'tablet'
      WHEN 'smart_tv' THEN 'smart_tv'
      WHEN 'voice_assistant' THEN 'voice_assistant'
      ELSE NULLIF(trim(`device_type`), '')
    END AS `device_type`,
    TRY_CAST(NULLIF(trim(`discount_amount`), '') AS DECIMAL(18,4)) AS `discount_amount`,
    NULLIF(trim(`fulfillment_ref`), '') AS `fulfillment_ref`,
    CASE lower(trim(`fulfillment_status`))
      WHEN 'unfulfilled' THEN 'unfulfilled'
      WHEN 'partially_fulfilled' THEN 'partially_fulfilled'
      WHEN 'fulfilled' THEN 'fulfilled'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`fulfillment_status`), '')
    END AS `fulfillment_status`,
    CASE WHEN lower(trim(`gift_order_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gift_order_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gift_order_flag`,
    NULLIF(trim(`ip_country_code`), '') AS `ip_country_code`,
    TRY_CAST(NULLIF(trim(`loyalty_points_earned`), '') AS INT) AS `loyalty_points_earned`,
    TRY_CAST(NULLIF(trim(`loyalty_points_redeemed`), '') AS INT) AS `loyalty_points_redeemed`,
    COALESCE(try_to_timestamp(trim(`order_date`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`order_date`) AS TIMESTAMP)) AS `order_date`,
    NULLIF(trim(`order_status`), '') AS `order_status`,
    TRY_CAST(NULLIF(trim(`order_total_amount`), '') AS DECIMAL(18,4)) AS `order_total_amount`,
    CASE lower(trim(`payment_method`))
      WHEN 'credit_card' THEN 'credit_card'
      WHEN 'debit_card' THEN 'debit_card'
      WHEN 'paypal' THEN 'paypal'
      WHEN 'apple_pay' THEN 'apple_pay'
      WHEN 'google_pay' THEN 'google_pay'
      WHEN 'gift_card' THEN 'gift_card'
      ELSE NULLIF(trim(`payment_method`), '')
    END AS `payment_method`,
    CASE lower(trim(`payment_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'authorized' THEN 'authorized'
      WHEN 'captured' THEN 'captured'
      WHEN 'failed' THEN 'failed'
      WHEN 'refunded' THEN 'refunded'
      WHEN 'partially_refunded' THEN 'partially_refunded'
      ELSE NULLIF(trim(`payment_status`), '')
    END AS `payment_status`,
    NULLIF(trim(`payment_transaction_ref`), '') AS `payment_transaction_ref`,
    COALESCE(try_to_date(trim(`promised_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`promised_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`promised_delivery_date`) AS DATE)) AS `promised_delivery_date`,
    NULLIF(trim(`promotion_code`), '') AS `promotion_code`,
    CASE WHEN lower(trim(`return_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`return_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `return_flag`,
    NULLIF(trim(`return_reason_code`), '') AS `return_reason_code`,
    NULLIF(trim(`ship_to_name`), '') AS `ship_to_name`,
    COALESCE(try_to_date(trim(`shipped_date`), 'yyyy-MM-dd'), try_to_date(trim(`shipped_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`shipped_date`) AS DATE)) AS `shipped_date`,
    TRY_CAST(NULLIF(trim(`shipping_amount`), '') AS DECIMAL(18,4)) AS `shipping_amount`,
    NULLIF(trim(`source_system_order_ref`), '') AS `source_system_order_ref`,
    CASE WHEN lower(trim(`subscription_order_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`subscription_order_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `subscription_order_flag`,
    TRY_CAST(NULLIF(trim(`subtotal_amount`), '') AS DECIMAL(18,4)) AS `subtotal_amount`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,4)) AS `tax_amount`,
    NULLIF(trim(`tracking_number`), '') AS `tracking_number`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_dtc_order
)
SELECT *
FROM typed
QUALIFY `dtc_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `dtc_order_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.dtc_order_line ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_dtc_order_line (
  CONSTRAINT `dtc_order_line_id_not_null` EXPECT (`dtc_order_line_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `quantity_ordered_not_negative` EXPECT (`quantity_ordered` IS NULL OR `quantity_ordered` >= 0) ON VIOLATION DROP ROW,
  CONSTRAINT `unit_price_not_negative` EXPECT (`unit_price` IS NULL OR `unit_price` >= 0),
  CONSTRAINT `line_subtotal_not_negative` EXPECT (`line_subtotal` IS NULL OR `line_subtotal` >= 0),
  CONSTRAINT `line_discount_amount_not_negative` EXPECT (`line_discount_amount` IS NULL OR `line_discount_amount` >= 0),
  CONSTRAINT `line_net_amount_not_negative` EXPECT (`line_net_amount` IS NULL OR `line_net_amount` >= 0),
  CONSTRAINT `tax_amount_not_negative` EXPECT (`tax_amount` IS NULL OR `tax_amount` >= 0),
  CONSTRAINT `line_total_amount_not_negative` EXPECT (`line_total_amount` IS NULL OR `line_total_amount` >= 0),
  CONSTRAINT `quantity_shipped_not_negative` EXPECT (`quantity_shipped` IS NULL OR `quantity_shipped` >= 0),
  CONSTRAINT `quantity_cancelled_not_negative` EXPECT (`quantity_cancelled` IS NULL OR `quantity_cancelled` >= 0)
)
COMMENT 'Silver: consumer.dtc_order_line typed and cleaned, one row per dtc_order_line_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`dtc_order_line_id`), '') AS BIGINT) AS `dtc_order_line_id`,
    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`dtc_order_id`), '') AS BIGINT) AS `dtc_order_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_line_id`), '') AS BIGINT) AS `outbound_order_line_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`subscription_id`), '') AS BIGINT) AS `subscription_id`,
    TRY_CAST(NULLIF(trim(`supply_atp_record_id`), '') AS BIGINT) AS `supply_atp_record_id`,
    COALESCE(try_to_date(trim(`actual_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_delivery_date`) AS DATE)) AS `actual_delivery_date`,
    COALESCE(try_to_date(trim(`actual_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_ship_date`) AS DATE)) AS `actual_ship_date`,
    NULLIF(trim(`brand_code`), '') AS `brand_code`,
    CASE lower(trim(`channel_code`))
      WHEN 'dtc_web' THEN 'DTC_WEB'
      WHEN 'dtc_mobile' THEN 'DTC_MOBILE'
      WHEN 'dtc_app' THEN 'DTC_APP'
      WHEN 'dtc_subscription' THEN 'DTC_SUBSCRIPTION'
      WHEN 'dtc_social' THEN 'DTC_SOCIAL'
      ELSE NULLIF(trim(`channel_code`), '')
    END AS `channel_code`,
    TRY_CAST(NULLIF(trim(`cost_of_goods_sold`), '') AS DECIMAL(18,4)) AS `cost_of_goods_sold`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`fulfillment_status`), '') AS `fulfillment_status`,
    CASE WHEN lower(trim(`gift_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gift_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gift_flag`,
    NULLIF(trim(`gtin`), '') AS `gtin`,
    CASE WHEN lower(trim(`hazmat_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_flag`,
    CASE WHEN lower(trim(`is_returned`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_returned`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_returned`,
    TRY_CAST(NULLIF(trim(`line_discount_amount`), '') AS DECIMAL(18,4)) AS `line_discount_amount`,
    TRY_CAST(NULLIF(trim(`line_discount_pct`), '') AS DECIMAL(7,4)) AS `line_discount_pct`,
    TRY_CAST(NULLIF(trim(`line_net_amount`), '') AS DECIMAL(18,4)) AS `line_net_amount`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    TRY_CAST(NULLIF(trim(`line_subtotal`), '') AS DECIMAL(18,4)) AS `line_subtotal`,
    TRY_CAST(NULLIF(trim(`line_total_amount`), '') AS DECIMAL(18,4)) AS `line_total_amount`,
    TRY_CAST(NULLIF(trim(`loyalty_points_earned`), '') AS INT) AS `loyalty_points_earned`,
    TRY_CAST(NULLIF(trim(`loyalty_points_redeemed`), '') AS INT) AS `loyalty_points_redeemed`,
    NULLIF(trim(`product_category_code`), '') AS `product_category_code`,
    NULLIF(trim(`product_name`), '') AS `product_name`,
    COALESCE(try_to_date(trim(`promised_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`promised_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`promised_delivery_date`) AS DATE)) AS `promised_delivery_date`,
    COALESCE(try_to_date(trim(`promised_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`promised_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`promised_ship_date`) AS DATE)) AS `promised_ship_date`,
    NULLIF(trim(`promotion_code`), '') AS `promotion_code`,
    TRY_CAST(NULLIF(trim(`quantity_cancelled`), '') AS INT) AS `quantity_cancelled`,
    TRY_CAST(NULLIF(trim(`quantity_ordered`), '') AS INT) AS `quantity_ordered`,
    TRY_CAST(NULLIF(trim(`quantity_shipped`), '') AS INT) AS `quantity_shipped`,
    CASE WHEN lower(trim(`regulatory_hold_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_hold_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_hold_flag`,
    NULLIF(trim(`return_reason_code`), '') AS `return_reason_code`,
    CASE WHEN lower(trim(`subscription_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`subscription_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `subscription_flag`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,4)) AS `tax_amount`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`unit_price`), '') AS DECIMAL(18,4)) AS `unit_price`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_dtc_order_line
)
SELECT *
FROM typed
QUALIFY `dtc_order_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `dtc_order_line_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.subscription ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_subscription (
  CONSTRAINT `subscription_id_not_null` EXPECT (`subscription_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: consumer.subscription typed and cleaned, one row per subscription_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`subscription_id`), '') AS BIGINT) AS `subscription_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`delivery_address_id`), '') AS BIGINT) AS `delivery_address_id`,
    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    NULLIF(trim(`acquisition_source`), '') AS `acquisition_source`,
    CASE WHEN lower(trim(`auto_renew_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`auto_renew_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `auto_renew_flag`,
    TRY_CAST(NULLIF(trim(`billing_cycle_day`), '') AS INT) AS `billing_cycle_day`,
    COALESCE(try_to_date(trim(`cancellation_date`), 'yyyy-MM-dd'), try_to_date(trim(`cancellation_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`cancellation_date`) AS DATE)) AS `cancellation_date`,
    CASE lower(trim(`cancellation_reason`))
      WHEN 'price_too_high' THEN 'price_too_high'
      WHEN 'product_dissatisfaction' THEN 'product_dissatisfaction'
      WHEN 'found_alternative' THEN 'found_alternative'
      WHEN 'no_longer_needed' THEN 'no_longer_needed'
      WHEN 'financial_hardship' THEN 'financial_hardship'
      WHEN 'other' THEN 'other'
      ELSE NULLIF(trim(`cancellation_reason`), '')
    END AS `cancellation_reason`,
    CASE WHEN lower(trim(`ccpa_opt_out_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`ccpa_opt_out_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `ccpa_opt_out_flag`,
    CASE lower(trim(`channel`))
      WHEN 'dtc_web' THEN 'dtc_web'
      WHEN 'dtc_mobile' THEN 'dtc_mobile'
      WHEN 'dtc_app' THEN 'dtc_app'
      WHEN 'retail_partner' THEN 'retail_partner'
      WHEN 'voice_assistant' THEN 'voice_assistant'
      ELSE NULLIF(trim(`channel`), '')
    END AS `channel`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`discount_rate`), '') AS DECIMAL(5,4)) AS `discount_rate`,
    COALESCE(try_to_date(trim(`end_date`), 'yyyy-MM-dd'), try_to_date(trim(`end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`end_date`) AS DATE)) AS `end_date`,
    TRY_CAST(NULLIF(trim(`failed_payment_count`), '') AS INT) AS `failed_payment_count`,
    CASE lower(trim(`frequency`))
      WHEN 'weekly' THEN 'weekly'
      WHEN 'bi_weekly' THEN 'bi_weekly'
      WHEN 'monthly' THEN 'monthly'
      WHEN 'bi_monthly' THEN 'bi_monthly'
      WHEN 'quarterly' THEN 'quarterly'
      ELSE NULLIF(trim(`frequency`), '')
    END AS `frequency`,
    CASE WHEN lower(trim(`gdpr_consent_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gdpr_consent_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gdpr_consent_flag`,
    COALESCE(try_to_date(trim(`last_order_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_order_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_order_date`) AS DATE)) AS `last_order_date`,
    TRY_CAST(NULLIF(trim(`net_price`), '') AS DECIMAL(18,4)) AS `net_price`,
    COALESCE(try_to_date(trim(`next_order_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_order_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_order_date`) AS DATE)) AS `next_order_date`,
    TRY_CAST(NULLIF(trim(`nps_score`), '') AS INT) AS `nps_score`,
    COALESCE(try_to_date(trim(`pause_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`pause_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`pause_end_date`) AS DATE)) AS `pause_end_date`,
    CASE lower(trim(`pause_reason`))
      WHEN 'financial_hardship' THEN 'financial_hardship'
      WHEN 'travel' THEN 'travel'
      WHEN 'product_overstock' THEN 'product_overstock'
      WHEN 'temporary_unavailability' THEN 'temporary_unavailability'
      WHEN 'other' THEN 'other'
      ELSE NULLIF(trim(`pause_reason`), '')
    END AS `pause_reason`,
    COALESCE(try_to_date(trim(`pause_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`pause_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`pause_start_date`) AS DATE)) AS `pause_start_date`,
    CASE lower(trim(`payment_method_type`))
      WHEN 'credit_card' THEN 'credit_card'
      WHEN 'debit_card' THEN 'debit_card'
      WHEN 'digital_wallet' THEN 'digital_wallet'
      WHEN 'bank_transfer' THEN 'bank_transfer'
      WHEN 'gift_card' THEN 'gift_card'
      ELSE NULLIF(trim(`payment_method_type`), '')
    END AS `payment_method_type`,
    NULLIF(trim(`payment_token_reference`), '') AS `payment_token_reference`,
    TRY_CAST(NULLIF(trim(`price`), '') AS DECIMAL(18,4)) AS `price`,
    NULLIF(trim(`promotion_code`), '') AS `promotion_code`,
    TRY_CAST(NULLIF(trim(`quantity`), '') AS INT) AS `quantity`,
    COALESCE(try_to_date(trim(`start_date`), 'yyyy-MM-dd'), try_to_date(trim(`start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`start_date`) AS DATE)) AS `start_date`,
    NULLIF(trim(`subscription_number`), '') AS `subscription_number`,
    CASE lower(trim(`subscription_status`))
      WHEN 'active' THEN 'active'
      WHEN 'paused' THEN 'paused'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'pending' THEN 'pending'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`subscription_status`), '')
    END AS `subscription_status`,
    CASE lower(trim(`subscription_type`))
      WHEN 'auto_replenishment' THEN 'auto_replenishment'
      WHEN 'subscription_box' THEN 'subscription_box'
      WHEN 'bundle' THEN 'bundle'
      WHEN 'trial' THEN 'trial'
      ELSE NULLIF(trim(`subscription_type`), '')
    END AS `subscription_type`,
    TRY_CAST(NULLIF(trim(`total_orders_fulfilled`), '') AS INT) AS `total_orders_fulfilled`,
    COALESCE(try_to_date(trim(`trial_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`trial_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`trial_end_date`) AS DATE)) AS `trial_end_date`,
    CASE WHEN lower(trim(`trial_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`trial_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `trial_flag`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_subscription
)
SELECT *
FROM typed
QUALIFY `subscription_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `subscription_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.loyalty_program ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_loyalty_program (
  CONSTRAINT `loyalty_program_id_not_null` EXPECT (`loyalty_program_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: consumer.loyalty_program typed and cleaned, one row per loyalty_program_id (latest record_audit_updated wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`brand_id`), '') AS BIGINT) AS `brand_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`predecessor_loyalty_program_id`), '') AS BIGINT) AS `predecessor_loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`cltv_estimate`), '') AS DECIMAL(12,2)) AS `cltv_estimate`,
    NULLIF(trim(`consent_status`), '') AS `consent_status`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`effective_from`), 'yyyy-MM-dd'), try_to_date(trim(`effective_from`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_from`) AS DATE)) AS `effective_from`,
    COALESCE(try_to_date(trim(`effective_until`), 'yyyy-MM-dd'), try_to_date(trim(`effective_until`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_until`) AS DATE)) AS `effective_until`,
    NULLIF(trim(`enrollment_channel`), '') AS `enrollment_channel`,
    COALESCE(try_to_date(trim(`enrollment_date`), 'yyyy-MM-dd'), try_to_date(trim(`enrollment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`enrollment_date`) AS DATE)) AS `enrollment_date`,
    NULLIF(trim(`loyalty_program_status`), '') AS `loyalty_program_status`,
    TRY_CAST(NULLIF(trim(`nps_score`), '') AS INT) AS `nps_score`,
    TRY_CAST(NULLIF(trim(`points_balance`), '') AS DECIMAL(12,2)) AS `points_balance`,
    TRY_CAST(NULLIF(trim(`points_earned`), '') AS DECIMAL(12,2)) AS `points_earned`,
    COALESCE(try_to_date(trim(`points_expiration_date`), 'yyyy-MM-dd'), try_to_date(trim(`points_expiration_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`points_expiration_date`) AS DATE)) AS `points_expiration_date`,
    CASE WHEN lower(trim(`privacy_opt_in`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`privacy_opt_in`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `privacy_opt_in`,
    NULLIF(trim(`program_code`), '') AS `program_code`,
    NULLIF(trim(`program_description`), '') AS `program_description`,
    NULLIF(trim(`program_name`), '') AS `program_name`,
    NULLIF(trim(`program_type`), '') AS `program_type`,
    COALESCE(try_to_timestamp(trim(`record_audit_created`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`record_audit_created`) AS TIMESTAMP)) AS `record_audit_created`,
    COALESCE(try_to_timestamp(trim(`record_audit_updated`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`record_audit_updated`) AS TIMESTAMP)) AS `record_audit_updated`,
    TRY_CAST(NULLIF(trim(`reward_rate`), '') AS DECIMAL(5,2)) AS `reward_rate`,
    NULLIF(trim(`tier_level`), '') AS `tier_level`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_loyalty_program
)
SELECT *
FROM typed
QUALIFY `loyalty_program_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `loyalty_program_id` ORDER BY `record_audit_updated` DESC NULLS LAST, _ingested_at DESC) = 1;

-- consumer.loyalty_tier ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.consumer_loyalty_tier (
  CONSTRAINT `loyalty_tier_id_not_null` EXPECT (`loyalty_tier_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: consumer.loyalty_tier typed and cleaned, one row per loyalty_tier_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`loyalty_tier_id`), '') AS BIGINT) AS `loyalty_tier_id`,
    TRY_CAST(NULLIF(trim(`loyalty_program_id`), '') AS BIGINT) AS `loyalty_program_id`,
    TRY_CAST(NULLIF(trim(`next_loyalty_tier_id`), '') AS BIGINT) AS `next_loyalty_tier_id`,
    NULLIF(trim(`benefits_description`), '') AS `benefits_description`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    TRY_CAST(NULLIF(trim(`discount_percent`), '') AS DECIMAL(5,2)) AS `discount_percent`,
    COALESCE(try_to_date(trim(`effective_from`), 'yyyy-MM-dd'), try_to_date(trim(`effective_from`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_from`) AS DATE)) AS `effective_from`,
    COALESCE(try_to_date(trim(`effective_until`), 'yyyy-MM-dd'), try_to_date(trim(`effective_until`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_until`) AS DATE)) AS `effective_until`,
    NULLIF(trim(`eligibility_criteria`), '') AS `eligibility_criteria`,
    CASE WHEN lower(trim(`exclusive_offers`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`exclusive_offers`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `exclusive_offers`,
    NULLIF(trim(`expiration_policy`), '') AS `expiration_policy`,
    CASE WHEN lower(trim(`free_shipping`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`free_shipping`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `free_shipping`,
    CASE WHEN lower(trim(`is_default`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_default`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_default`,
    NULLIF(trim(`loyalty_tier_status`), '') AS `loyalty_tier_status`,
    TRY_CAST(NULLIF(trim(`max_points_per_year`), '') AS BIGINT) AS `max_points_per_year`,
    TRY_CAST(NULLIF(trim(`points_multiplier`), '') AS DECIMAL(5,2)) AS `points_multiplier`,
    CASE WHEN lower(trim(`priority_support`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`priority_support`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `priority_support`,
    NULLIF(trim(`promotional_code`), '') AS `promotional_code`,
    TRY_CAST(NULLIF(trim(`required_points`), '') AS BIGINT) AS `required_points`,
    TRY_CAST(NULLIF(trim(`required_spend_usd`), '') AS DECIMAL(12,2)) AS `required_spend_usd`,
    TRY_CAST(NULLIF(trim(`reward_points_per_dollar`), '') AS DECIMAL(5,2)) AS `reward_points_per_dollar`,
    TRY_CAST(NULLIF(trim(`spend_multiplier`), '') AS DECIMAL(5,2)) AS `spend_multiplier`,
    NULLIF(trim(`tier_code`), '') AS `tier_code`,
    NULLIF(trim(`tier_name`), '') AS `tier_name`,
    TRY_CAST(NULLIF(trim(`tier_rank`), '') AS INT) AS `tier_rank`,
    NULLIF(trim(`tier_type`), '') AS `tier_type`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.consumer_loyalty_tier
)
SELECT *
FROM typed
QUALIFY `loyalty_tier_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `loyalty_tier_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
